    [22630]={name="Atiesh, Greatstaff of the Guardian",quality=5,ilvl=90,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Atiesh, Greatstaff of the Guardian'.",questName="Atiesh, Greatstaff of the Guardian",lore="The Guardian's staff, broken and scattered. Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it.",proc="Use: Creates a portal, teleporting group members that use it to Karazhan. (1 Min Cooldown)"},
    [22657]={name="Amulet of the Dawn",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"},
    [22667]={name="Bracers of Hope",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn'. Pick it over the other reward choices.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."},
    [22943]={name="Malice Stone Pendant",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Grand Widow Faerlina.",zone="Naxxramas",npc="Grand Widow Faerlina",lore="A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."},
    [22954]={name="Kiss of the Spider",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Maexxna.",zone="Naxxramas",npc="Maexxna",lore="A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs.",proc="Use: Increases your haste rating by 200 for 15 sec. (2 Min Cooldown)"},
    [23001]={name="Eye of Diminution",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter.",proc="Use: Reduces the threat you generate by [35 - max(0, Level - 60)]% for 20 sec. (2 Min Cooldown)"},
    [23025]={name="Seal of the Damned",quality=4,ilvl=85,reqLevel=60,sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
